program P;
uses sockets, baseunix;
var s: longint;
    a: sockaddr_in;
begin
  s := fpSocket(AF_INET, SOCK_STREAM, 0);
  if s >= 0 then begin
    a.sin_family := AF_INET;
    a.sin_port := htons(80);
    a.sin_addr := StrToNetAddr('93.184.216.34');
    fpConnect(s, @a, sizeof(a));
    fpClose(s);
  end;
end.
